window.__votdWeek && window.__votdWeek({"week":"2027-09-06","reading":"2 Corinthians 1–7","days":[{"d":"2027-09-06","ref":"2 Corinthians 1:9","b":"2 Corinthians","c":1,"v":9,"he":"וַאֲנַחְנוּ בִלְבָבֵנוּ חָרַצְנוּ לָנוּ אֶת־הַמָּוֶת לְמַעַן אֲשֶׁר־לֹא נִבְטַח בְּנַפְשֵׁנוּ כִּי אִם־בֵּאלֹהִים הַמְחַיֶּה אֶת־הַמֵּתִים׃","en":"But we had the sentence of death in ourselves, that we should not trust in ourselves, but in God which raiseth the dead:"},{"d":"2027-09-07","ref":"2 Corinthians 3:1","b":"2 Corinthians","c":3,"v":1,"he":"הֲנָחֵל עוֹד לְשַׁבֵּחַ עַצְמֵנוּ הַאִם־צְרִיכִים אֲנַחְנוּ כַּאֲחֵרִים לְאִגְּרוֹת אֲלֵיכֶם אוֹ מִכֶּם מַזְכִּירוֹת אֹתָנוּ לָשֶׁבַח׃","en":"Do we begin again to commend ourselves? or need we, as some others, epistles of commendation to you, or letters of commendation from you?"},{"d":"2027-09-08","ref":"2 Corinthians 3:16","b":"2 Corinthians","c":3,"v":16,"he":"אַךְ בְּעֵת שׁוּבָם אֶל־הָאָדוֹן יוּסַר הַמַּסְוֶה׃","en":"Nevertheless when it shall turn to the Lord, the veil shall be taken away."},{"d":"2027-09-09","ref":"2 Corinthians 4:4","b":"2 Corinthians","c":4,"v":4,"he":"אֲשֶׁר אֵל הָעוֹלָם הַזֶּה עִוֵּר בָּהֶם אֶת־מַחְשְׁבוֹת חַסְרֵי הָאֱמוּנָה לְבִלְתִּי זְרֹחַ לָהֶם נֹגַהּ בְּשׂוֹרַת כְּבוֹד הַמָּשִׁיחַ אֲשֶׁר הוּא צֶלֶם הָאֱלֹהִים׃","en":"In whom the god of this world hath blinded the minds of them which believe not, lest the light of the glorious gospel of Christ, who is the image of God, should shine unto them."},{"d":"2027-09-10","ref":"2 Corinthians 4:17","b":"2 Corinthians","c":4,"v":17,"he":"כִּי לַחֲצֵנוּ שֶׁהוּא קַל וְאֵינוֹ אֶלָּא לְרָגַע יָבִיא לָנוּ כְּבוֹד עוֹלָמִים גָּדוֹל וָרָב עַד־לִמְאֹד׃","en":"For our light affliction, which is but for a moment, worketh for us a far more exceeding and eternal weight of glory;"},{"d":"2027-09-11","ref":"2 Corinthians 6:6","b":"2 Corinthians","c":6,"v":6,"he":"בְּטׇהֳרָה וּבְדַעַת וּבְאֹרֶךְ רוּחַ וּבְחֶסֶד וּבְרוּחַ־הַקֹּדֶשׁ וּבְאַהֲבָה לֹא צְבוּעָה׃","en":"By pureness, by knowledge, by longsuffering, by kindness, by the Holy Ghost, by love unfeigned,"},{"d":"2027-09-12","ref":"2 Corinthians 7:10","b":"2 Corinthians","c":7,"v":10,"he":"כִּי הָעַצֶּבֶת שֶׁהִיא כִּרְצוֹן אֱלֹהִים גֹּרֶמֶת תְּשׁוּבָה לִישׁוּעָה אֲשֶׁר אִישׁ לֹא יִתְחָרֵט עָלֶיהָ וְעַצְּבַת הָעוֹלָם מְבִיאָה לִידֵי מִיתָה׃","en":"For godly sorrow worketh repentance to salvation not to be repented of: but the sorrow of the world worketh death."}]});
